{# =====================================================================
   KILN DPR · A3 landscape · Print Format on "DRI Production" (Custom Format, Jinja)
   One kiln per sheet, laid out like the plant's DPR spreadsheet:
   PRODUCTION · MATERIAL · STOCK / LOGISTICS.
   Cells whose source is not settled yet are left blank (see the settings below).
   ===================================================================== #}

{# ---------- Settings ---------- #}
{% set COMPANY = "NACHIKETA POWER AND STEEL PVT LTD" %}
{% set TARGET_MONTH = 15000 %}             {# DRI target per month, MT #}
{% set TARGET_YEAR = 165000 %}             {# DRI target per financial year, MT #}
{# ABP (annual business plan) monthly targets, Apr → Mar: 15,000 a month with one maintenance month at 0 (August) = 165,000 #}
{% set ABP_MONTHLY = [15000, 15000, 15000, 15000, 0, 15000, 15000, 15000, 15000, 15000, 15000, 15000] %}
{# ABP specific-consumption targets (MT per MT DRI; power in units per MT). Leave none to show blank. #}
{% set ABP_SPEC = {"pellets": none, "iron": none, "coal": none, "im_coal": none, "power": none, "water": none, "store": none, "dolo": none} %}
{% set BREAKDOWN_TABLES = ["table_atyf"] %} {# DRI Production child-table field(s) holding kiln breakdowns (doctype "Production Breakdown") #}
{% set USE_QUALITY_QUERY = True %}         {# fill the lab blocks from the saved report "Quality Query" when it exists #}
{% set FEED_RATE_FIELD = none %}           {# DRI Production field for feed rate, e.g. "feed_rate"; none = blank #}
{# Store consumption, as in the report "Store Issue Cost Center wise": issue value ÷ (days × STORE_MT_PER_DAY) #}
{% set STORE_MT_PER_DAY = 550 %}
{% set STORE_EXCLUDE_GROUPS = ["Coal", "Iron Ore"] %}
{# Store sections: cost centres are matched to these by keyword; anything else goes to "Other". #}
{# Item codes. Dispatch and product stock come from the weighbridge (outward) and the stock ledger. #}
{% set DISPATCH = [("DRI LUMPS", ["FG-0001"]), ("DRI FINES", []), ("IRON FINES", []), ("CHAR", ["BY-0001", "BY-0004"]), ("ESP DUST / ASH", ["BY-0002"])] %}
{% set PRODUCT_STOCK = [("LUMPS", ["FG-0001"]), ("FINES", []), ("CHAR", ["BY-0001", "BY-0004"])] %}
{# Raw material balancing: label, item codes, DRI Production consumption field (plant total) #}
{% set RM_BALANCE = [("PELLET", ["RM-0003"], "pel"), ("IRON ORE", [], "ore"), ("RB-1", [], "rb1"), ("RB-2", [], "rb2"), ("RB-2 FINES COAL", ["CO-0001"], none), ("WASH COAL", ["RM-0002"], "wash"), ("DOM-COAL", ["RM-0001"], "romb"), ("DOLOMITE", ["RM-0004"], "dolo")] %}
{# Breakdown rows whose remarks contain these words are feed losses: listed under FEED LOSS and left out of breakdown totals #}
{% set FEED_LOSS_WORDS = ["INJECTION", "FEED LOSS"] %}
{% set NA = "--" %}                        {# shown where there is no data #}
{% set STORE_SECTIONS = [("OPRN", ["OPRN", "OPERATION", "PRODUCTION", "PROCESS"]), ("MECH", ["MECH"]), ("EEC&EI", ["EEC", "ELEC", "E&I", "INSTR"]), ("QC LAB", ["QC", "LAB", "QUALITY"]), ("CIVIL", ["CIVIL"]), ("CPP", ["CPP", "POWER"])] %}

{# ---------- The report day ---------- #}
{% set d = doc %}
{% set U = frappe.utils %}
{% set kiln = d.kiln_no %}
{% set camp = d.campaign_no %}
{% set day = U.getdate(d.production_date) %}
{% set mstart = U.get_first_day(day) %}
{% set dim = U.get_last_day(day).day %}
{% set fy_y = day.year if day.month >= 4 else day.year - 1 %}
{% set fy_start = U.getdate(fy_y ~ "-04-01") %}
{% set fy_end = U.getdate((fy_y + 1) ~ "-03-31") %}
{% set fy_days = U.date_diff(fy_end, fy_start) + 1 %}
{% set fy_elapsed = U.date_diff(day, fy_start) + 1 %}
{% set P = {"k": kiln, "c": camp, "d": day, "m": mstart, "y": fy_start} %}
{# Targets from the monthly plan: this month's target pro-rata, and the year to date (past months in full + this month pro-rata) #}
{% set mi = (day.month - 4) % 12 %}
{% set target_mtd = ABP_MONTHLY[mi] * day.day / dim %}
{% set target_ytd = (ABP_MONTHLY[:mi]|sum) + target_mtd %}

{# ---------- Formatting ---------- #}
{% macro n0(v) %}{% if v is none or v == "" %}{{ NA }}{% else %}{{ "{:,.0f}".format(v|float) }}{% endif %}{% endmacro %}
{% macro n1(v) %}{% if v is none or v == "" %}{{ NA }}{% else %}{{ "{:,.1f}".format(v|float) }}{% endif %}{% endmacro %}
{% macro n2(v) %}{% if v is none or v == "" %}{{ NA }}{% else %}{{ "{:,.2f}".format(v|float) }}{% endif %}{% endmacro %}
{% macro n3(v) %}{% if v is none or v == "" %}{{ NA }}{% else %}{{ "{:,.3f}".format(v|float) }}{% endif %}{% endmacro %}
{# a ÷ b × k, blank when b is zero #}
{% macro div(a, b, digits=2, k=1) %}{% if (b or 0)|float != 0 %}{% set v = ((a or 0)|float) * k / (b|float) %}{% if digits == 0 %}{{ n0(v) }}{% elif digits == 1 %}{{ n1(v) }}{% elif digits == 3 %}{{ n3(v) }}{% else %}{{ n2(v) }}{% endif %}{% else %}{{ NA }}{% endif %}{% endmacro %}
{# a value, or "--" when it is zero / missing #}
{% macro nz(v, digits=0) %}{% if (v or 0)|float != 0 %}{% if digits == 0 %}{{ n0(v) }}{% elif digits == 1 %}{{ n1(v) }}{% elif digits == 3 %}{{ n3(v) }}{% else %}{{ n2(v) }}{% endif %}{% else %}{{ NA }}{% endif %}{% endmacro %}
{# a ratio a ÷ b, or "--" when a is zero (nothing used) #}
{% macro per(a, b, digits=2) %}{% if (a or 0)|float != 0 %}{{ div(a, b, digits) }}{% else %}{{ NA }}{% endif %}{% endmacro %}

{# =====================================================================
   DATA
   ===================================================================== #}

{# ---------- Day / MTD / campaign / YTD totals for this kiln, in one query ---------- #}
{% set SCOPES = {
  "tdy": "production_date = %(d)s",
  "mtd": "production_date BETWEEN %(m)s AND %(d)s",
  "cmp": "campaign_no = %(c)s AND production_date <= %(d)s",
  "ytd": "production_date BETWEEN %(y)s AND %(d)s"} %}
{% set METRICS = {
  "dri": "IFNULL(dri_production,0)",
  "pel": "IFNULL(cons_pellets,0)",
  "ore": "IFNULL(cons_sized_ore,0)",
  "rb1": "IFNULL(cons_rb1,0)",
  "rb2": "IFNULL(cons_rb2,0)",
  "wash": "IFNULL(cons_washed,0)",
  "romb": "IFNULL(cons_rom_b,0)",
  "dolo": "IFNULL(cons_dolomite,0)",
  "a_hrs": "IFNULL(grade_a_hrs,0)",
  "b_hrs": "IFNULL(grade_b_hrs,0)",
  "fe_num": "CASE WHEN fe_m > 0 THEN IFNULL(dri_production,0) * fe_m ELSE 0 END",
  "fe_den": "CASE WHEN fe_m > 0 THEN IFNULL(dri_production,0) ELSE 0 END",
  "kwh": "IFNULL(power_kwh,0)",
  "steam": "IFNULL(total_steam,0)",
  "dri_kwh": "IFNULL(dri_power_consumption,0)",
  "feed": ("IFNULL(" ~ FEED_RATE_FIELD ~ ",0)") if FEED_RATE_FIELD else "0"} %}
{% set cols = [] %}
{% for s, cond in SCOPES.items() %}
  {% set _ = cols.append("COUNT(DISTINCT CASE WHEN " ~ cond ~ " THEN production_date END) AS " ~ s ~ "_days") %}
  {% for m, expr in METRICS.items() %}{% set _ = cols.append("SUM(CASE WHEN " ~ cond ~ " THEN " ~ expr ~ " ELSE 0 END) AS " ~ s ~ "_" ~ m) %}{% endfor %}
{% endfor %}
{% set A = frappe.db.sql("SELECT " ~ cols|join(", ") ~ " FROM `tabDRI Production` WHERE docstatus < 2 AND kiln_no = %(k)s AND production_date <= %(d)s AND (production_date >= %(y)s OR campaign_no = %(c)s)", P, as_dict=1)[0] %}
{# Read one scope's figures as a dict: S("mtd").dri etc. #}
{% set SC = {} %}
{% for s in SCOPES %}
  {% set x = {"days": A[s ~ "_days"]|int} %}
  {% for m in METRICS %}{% set _ = x.update({m: A[s ~ "_" ~ m]|float}) %}{% endfor %}
  {# DOM coal = ROM (ROM B + RB1); washed coal is shown on its own; D coal (ratio) = all domestic coal #}
  {% set _ = x.update({"coal": x.rb1 + x.rb2 + x.wash + x.romb, "dom": x.rb1 + x.romb, "dcoal": x.rb1 + x.wash + x.romb}) %}
  {% set _ = SC.update({s: x}) %}
{% endfor %}
{% set T = SC.tdy %}{% set M = SC.mtd %}{% set C = SC.cmp %}{% set Y = SC.ytd %}

{# ---------- Monthly DRI for the ABP table, and the kiln's history for "ever best" ---------- #}
{% set months_all = frappe.db.sql("SELECT SUBSTRING(production_date,1,7) AS m, SUM(IFNULL(dri_production,0)) AS dri FROM `tabDRI Production` WHERE docstatus < 2 AND kiln_no = %(k)s AND production_date <= %(d)s GROUP BY SUBSTRING(production_date,1,7)", P, as_dict=1) %}
{% set mdri = {} %}{% for r in months_all %}{% set _ = mdri.update({r.m: r.dri|float}) %}{% endfor %}
{% set best_day = frappe.db.sql("SELECT production_date AS d, SUM(IFNULL(dri_production,0)) AS dri FROM `tabDRI Production` WHERE docstatus < 2 AND kiln_no = %(k)s AND production_date <= %(d)s GROUP BY production_date ORDER BY dri DESC LIMIT 1", P, as_dict=1) %}
{# Group months into financial quarters, halves and years #}
{% set BEST = {"q": {}, "h": {}, "y": {}} %}
{% for r in months_all %}
  {% set yy = r.m[:4]|int %}{% set mm = r.m[5:7]|int %}
  {% set fy = yy if mm >= 4 else yy - 1 %}
  {% set q = ((mm - 4) % 12) // 3 + 1 %}
  {% set fyl = "FY" ~ ("%02d"|format(fy % 100)) ~ "-" ~ ("%02d"|format((fy + 1) % 100)) %}
  {% for key, label in [("q", "Q" ~ q ~ " " ~ fyl), ("h", ("H1 " if q <= 2 else "H2 ") ~ fyl), ("y", fyl)] %}
    {% set _ = BEST[key].update({label: BEST[key].get(label, 0) + (r.dri|float)}) %}
  {% endfor %}
{% endfor %}
{% macro best_of(dct) %}{% set ns = namespace(k="", v=0) %}{% for k, v in dct.items() %}{% if v > ns.v %}{% set ns.k = k %}{% set ns.v = v %}{% endif %}{% endfor %}{{ ns.k }}|{{ ns.v }}{% endmacro %}
{% set best_month = namespace(k="", v=0) %}{% for k, v in mdri.items() %}{% if v > best_month.v %}{% set best_month.k = k %}{% set best_month.v = v %}{% endif %}{% endfor %}

{# ---------- Breakdowns (minutes) by department group ---------- #}
{% set BD_COLS = ["Ops", "Maint.", "RMHS", "E & I", "OTHER"] %}
{# 1 when a breakdown row is really a feed loss (its remarks mention one of FEED_LOSS_WORDS) #}
{% set fl = [] %}{% for w in FEED_LOSS_WORDS %}{% set _ = fl.append("UPPER(IFNULL(b.remarks,'')) LIKE '%%" ~ w ~ "%%'") %}{% endfor %}
{% set FEED_SQL = "CASE WHEN " ~ (fl|join(" OR ") or "1=0") ~ " THEN 1 ELSE 0 END" %}
{% macro bd_group(dept) %}{% set u = (dept or "")|upper %}{% if "RMHS" in u %}RMHS{% elif "E&I" in u|replace(" ", "") or "ELEC" in u or "INSTR" in u or "EI" == u|replace(" ", "") %}E & I{% elif "MAINT" in u or "MECH" in u %}Maint.{% elif "OP" in u %}Ops{% else %}OTHER{% endif %}{% endmacro %}
{% set bd_rows = frappe.db.sql("
  SELECT b.department AS dept, (" ~ FEED_SQL ~ ") AS feed,
         SUM(CASE WHEN p.production_date = %(d)s THEN IFNULL(b.minutes,0) ELSE 0 END) AS tdy,
         SUM(CASE WHEN p.production_date BETWEEN %(m)s AND %(d)s THEN IFNULL(b.minutes,0) ELSE 0 END) AS mtd,
         SUM(CASE WHEN p.campaign_no = %(c)s THEN IFNULL(b.minutes,0) ELSE 0 END) AS cmp,
         SUM(CASE WHEN p.production_date >= %(y)s THEN IFNULL(b.minutes,0) ELSE 0 END) AS ytd
  FROM `tabProduction Breakdown` b JOIN `tabDRI Production` p ON p.name = b.parent
  WHERE p.docstatus < 2 AND p.kiln_no = %(k)s AND p.production_date <= %(d)s AND (p.production_date >= %(y)s OR p.campaign_no = %(c)s)
    AND b.parenttype = 'DRI Production' AND b.parentfield IN %(pf)s
  GROUP BY b.department, (" ~ FEED_SQL ~ ")
", {"k": kiln, "c": camp, "d": day, "m": mstart, "y": fy_start, "pf": BREAKDOWN_TABLES}, as_dict=1) %}
{% set BD = {} %}
{% for g in BD_COLS %}{% set _ = BD.update({g: {"tdy": 0, "mtd": 0, "cmp": 0, "ytd": 0}}) %}{% endfor %}
{% for r in bd_rows if not (r.feed|int) %}{% set g = bd_group(r.dept)|trim %}{% for s in ["tdy", "mtd", "cmp", "ytd"] %}{% set _ = BD[g].update({s: BD[g][s] + (r[s]|float)}) %}{% endfor %}{% endfor %}
{% set bd_today = frappe.db.sql("SELECT b.department AS dept, b.minutes AS mins, b.remarks AS remarks, " ~ FEED_SQL ~ " AS feed FROM `tabProduction Breakdown` b JOIN `tabDRI Production` p ON p.name = b.parent WHERE p.docstatus < 2 AND p.kiln_no = %(k)s AND p.production_date = %(d)s AND b.parenttype = 'DRI Production' AND b.parentfield IN %(pf)s ORDER BY b.idx", {"k": kiln, "d": day, "pf": BREAKDOWN_TABLES}, as_dict=1) %}
{% set feed_today = bd_today|selectattr("feed", "equalto", 1)|list %}
{% set bd_notes = {} %}{% for r in bd_today if r.remarks and not (r.feed|int) %}{% set g = bd_group(r.dept)|trim %}{% set _ = bd_notes.update({g: (bd_notes.get(g, "") ~ (" · " if bd_notes.get(g) else "") ~ r.remarks)}) %}{% endfor %}

{# ---------- Lab analysis from the saved report "Quality Query" (latest values) ---------- #}
{% set LAB = {"IO": {}, "PELLETS": {}, "DOLOMITE": {}, "RB1": {}, "RB2": {}, "WASH": {}, "DOM": {}} %}
{% macro key(p) %}{% set k = (p or "")|lower|replace(" ", "")|replace(".", "")|replace("(", "")|replace(")", "")|replace("%", "") %}{{ {"mois": "moisture", "sulp": "s", "sulphur": "s", "sulfur": "s", "volatilematter": "vm", "fixedcarbon": "fc", "sio2al2o3": "sio2+al2o3"}.get(k, k) }}{% endmacro %}
{% if USE_QUALITY_QUERY and frappe.db.exists("Report", "Quality Query") %}
  {% for r in frappe.db.sql(frappe.get_doc("Report", "Quality Query").query, {"kiln_no": kiln, "campaign_no": camp}, as_dict=1) or [] %}
    {% set rm = (r.get("rm") or r.get("RM") or "")|upper %}
    {% set prm = r.get("param") %}
    {% set full = r.get("parameter") or r.get("Parameter") or "" %}
    {% if not rm %}{% set fw = (full.split(" ", 1)[0] if " " in full else full)|upper %}{% set rm = "IO" if fw in ["IO", "IRON", "IRON ORE"] else ("PELLETS" if "PELLET" in fw else ("DOLOMITE" if "DOLO" in fw else ("RB2" if fw == "RB2" else ("RB1" if fw == "RB1" else ("DOM" if fw in ["DOM1", "DOM 1"] else ("WASH" if fw in ["DOM2", "DOM 2"] else ""))))))  %}{% endif %}
    {% if rm in ["DOM1"] %}{% set rm = "DOM" %}{% elif rm in ["DOM2"] %}{% set rm = "WASH" %}{% elif rm == "PELLET" %}{% set rm = "PELLETS" %}{% endif %}
    {% if not prm %}{% set prm = full.split(" ", 1)[1] if " " in full else full %}{% endif %}
    {% if rm in LAB %}{% set _ = LAB[rm].update({key(prm)|trim: r.get("latest") if r.get("latest") is not none else r.get("Latest")}) %}{% endif %}
  {% endfor %}
{% endif %}
{# zero means "not tested" and is left blank #}
{% macro lab(rm, label) %}{% set v = LAB[rm].get(key(label)|trim) %}{% if v is number %}{{ nz(v, 2) }}{% elif v %}{{ v }}{% else %}{{ NA }}{% endif %}{% endmacro %}

{# ---------- Store consumption (₹ per ton), same logic as the report "Store Issue Cost Center wise" ---------- #}
{# Issues = stock entry rows taken out of a warehouse, with a cost centre, excluding Coal / Iron Ore item groups.
   ₹/T = issue value ÷ (days × STORE_MT_PER_DAY): one day for Today, days since 1 April for FY. #}
{% set STORE = {"tdy": {}, "ytd": {}} %}
{% set fy_n = U.date_diff(day, fy_start) + 1 %}
{% for r in frappe.db.sql("
  SELECT sed.cost_center AS cc,
         SUM(CASE WHEN se.posting_date = %(d)s THEN ABS(IFNULL(sed.basic_amount,0)) ELSE 0 END) AS day_amt,
         SUM(ABS(IFNULL(sed.basic_amount,0))) AS fy_amt
  FROM `tabStock Entry` se
  JOIN `tabStock Entry Detail` sed ON sed.parent = se.name
  JOIN `tabItem` i ON i.name = sed.item_code
  WHERE se.docstatus = 1 AND se.posting_date BETWEEN %(y)s AND %(d)s
    AND IFNULL(sed.s_warehouse,'') != '' AND IFNULL(sed.cost_center,'') != ''
    AND IFNULL(i.item_group,'') NOT IN %(ex)s
  GROUP BY sed.cost_center
", {"d": day, "y": fy_start, "ex": STORE_EXCLUDE_GROUPS}, as_dict=1) %}
  {% set u = (r.cc or "")|upper %}{% set ns = namespace(sec="Other") %}
  {% for sec, words in STORE_SECTIONS %}{% if ns.sec == "Other" %}{% for w in words %}{% if w in u %}{% set ns.sec = sec %}{% endif %}{% endfor %}{% endif %}{% endfor %}
  {% set _ = STORE.tdy.update({ns.sec: STORE.tdy.get(ns.sec, 0) + (r.day_amt|float) / STORE_MT_PER_DAY}) %}
  {% set _ = STORE.ytd.update({ns.sec: STORE.ytd.get(ns.sec, 0) + (r.fy_amt|float) / (fy_n * STORE_MT_PER_DAY)}) %}
{% endfor %}

{# ---------- Weighbridge (outward dispatch, inward receipts) and the stock ledger ---------- #}
{% set at6 = " " ~ "06:00:00" %}
{% set W_MT = "(CASE WHEN IFNULL(w.net_weight,0) > 0 THEN w.net_weight WHEN IFNULL(w.gross_weight,0) > 0 AND IFNULL(w.tare_weight,0) > 0 AND w.gross_weight >= w.tare_weight THEN w.gross_weight - w.tare_weight ELSE 0 END) / 1000.0" %}
{# All item codes used below, and the Weighments material value for each (item code or item name) #}
{% set CODES = [] %}{% for _l, cs in DISPATCH + PRODUCT_STOCK %}{% for c in cs %}{% if c not in CODES %}{% set _ = CODES.append(c) %}{% endif %}{% endfor %}{% endfor %}
{% for _l, cs, _f in RM_BALANCE %}{% for c in cs %}{% if c not in CODES %}{% set _ = CODES.append(c) %}{% endif %}{% endfor %}{% endfor %}
{% set ITEMS = {} %}{% for r in (frappe.db.sql("SELECT name, item_name, stock_uom FROM `tabItem` WHERE name IN %(c)s", {"c": CODES}, as_dict=1) if CODES else []) %}{% set _ = ITEMS.update({r.name: r}) %}{% endfor %}
{% set UOM_MT = {"KG": 0.001, "KGS": 0.001, "KILOGRAM": 0.001, "QTL": 0.1, "QUINTAL": 0.1, "MT": 1, "TON": 1, "TONS": 1, "TONNE": 1, "TONNES": 1} %}
{# Weighbridge net MT per item code and movement for the day, MTD and FY (second weighing 6 AM – 6 AM) #}
{% set WB = {} %}
{% if CODES %}
{% for r in frappe.db.sql("
  SELECT i.name AS code, LOWER(TRIM(IFNULL(w.movement,''))) AS mv,
         SUM(CASE WHEN w.second_weight_time >= %(dt)s THEN " ~ W_MT ~ " ELSE 0 END) AS tdy,
         SUM(CASE WHEN w.second_weight_time >= %(mt)s THEN " ~ W_MT ~ " ELSE 0 END) AS mtd,
         SUM(" ~ W_MT ~ ") AS ytd
  FROM `tabWeighments` w JOIN `tabItem` i ON (w.material = i.name OR w.material = i.item_name)
  WHERE w.docstatus != 2 AND i.name IN %(c)s AND w.second_weight_time >= %(yt)s AND w.second_weight_time < %(we)s
  GROUP BY i.name, LOWER(TRIM(IFNULL(w.movement,'')))
", {"c": CODES, "dt": day|string ~ at6, "mt": mstart|string ~ at6, "yt": fy_start|string ~ at6, "we": U.add_days(day, 1)|string ~ at6}, as_dict=1) %}
  {% set _ = WB.update({r.code ~ "|" ~ r.mv: r}) %}
{% endfor %}
{% endif %}
{% macro wb(codes, mv, scope) %}{% set ns = namespace(v=0, n=0) %}{% for c in codes %}{% set r = WB.get(c ~ "|" ~ mv) %}{% if r %}{% set ns.v = ns.v + (r[scope]|float) %}{% set ns.n = ns.n + 1 %}{% endif %}{% endfor %}{{ ns.v if codes else "" }}{% endmacro %}
{# Book stock (MT) per item code at a moment, from the stock ledger #}
{% macro stock_sql(t) %}SELECT item_code AS code, SUM(actual_qty) AS qty FROM `tabStock Ledger Entry` WHERE is_cancelled = 0 AND item_code IN %(c)s AND TIMESTAMP(posting_date, posting_time) < '{{ t }}' GROUP BY item_code{% endmacro %}
{% set STK = {"open": {}, "close": {}} %}
{% if CODES %}
{% for key, t in [("open", day|string ~ at6), ("close", U.add_days(day, 1)|string ~ at6)] %}
  {% for r in frappe.db.sql(stock_sql(t)|string, {"c": CODES}, as_dict=1) %}
    {% set it = ITEMS.get(r.code) %}{% set fct = UOM_MT.get(((it.stock_uom if it else "") or "")|upper|trim) %}
    {% if fct is not none %}{% set _ = STK[key].update({r.code: (r.qty|float) * fct}) %}{% endif %}
  {% endfor %}
{% endfor %}
{% endif %}
{% macro stk(codes, key) %}{% set ns = namespace(v=0, any=false) %}{% for c in codes %}{% if c in STK[key] %}{% set ns.v = ns.v + STK[key][c] %}{% set ns.any = true %}{% endif %}{% endfor %}{{ ns.v if ns.any else "" }}{% endmacro %}
{# Plant consumption for the day (all kilns), for the yard balance #}
{% set PC = frappe.db.sql("SELECT SUM(IFNULL(cons_pellets,0)) AS pel, SUM(IFNULL(cons_sized_ore,0)) AS ore, SUM(IFNULL(cons_rb1,0)) AS rb1, SUM(IFNULL(cons_rb2,0)) AS rb2, SUM(IFNULL(cons_washed,0)) AS wash, SUM(IFNULL(cons_rom_b,0)) AS romb, SUM(IFNULL(cons_dolomite,0)) AS dolo FROM `tabDRI Production` WHERE docstatus < 2 AND production_date = %(d)s", P, as_dict=1)[0] %}

{# =====================================================================
   LAYOUT
   ===================================================================== #}
<style>
  /* PDF options: Frappe reads these from a ".print-format" rule. */
  .print-format { page-size: A3; orientation: Landscape; margin-top: 6mm; margin-bottom: 6mm; margin-left: 6mm; margin-right: 6mm; }
  .print-format { max-width: none !important; width: 100% !important; padding: 0 !important; margin: 0 !important; }
  .dpr, .dpr table, .dpr td, .dpr th { font-family: Arial, Helvetica, sans-serif; color: #111; }
  .dpr { font-size: 10px; position: relative; }
  .dpr table { border-collapse: collapse; width: 100%; table-layout: fixed; }
  /* Frappe's print stylesheet forces "padding: 6px !important; vertical-align: top !important" on cells; override it to keep one page. */
  .print-format .dpr td, .print-format .dpr th, .dpr td, .dpr th { border: 1px solid #8c8c8c !important; padding: 1px 3px !important; height: 17px !important; line-height: 14px !important; font-size: 10.5px !important; vertical-align: middle !important; white-space: nowrap; overflow: hidden; }
  .print-format .dpr table, .dpr table { margin: 0 !important; }
  .dpr th { background: #dbe7f3; font-weight: bold; text-align: center; }
  .dpr .g { background: #e8efe1; font-weight: bold; text-align: center; }
  .dpr .lbl { background: #dbe7f3; font-weight: bold; text-align: left; }
  .dpr .c { text-align: center; }
  .dpr .r { text-align: center; }
  .dpr .b { font-weight: bold; }
