</style>

<div class="dpr">
{% if d.docstatus == 0 %}<div class="draft">DRAFT</div>{% endif %}
<div class="title">{{ COMPANY }} · DAILY PRODUCTION REPORT · {{ kiln|upper }}</div>
<div class="sub">DATE: {{ frappe.format_date(day, "dd MMM yyyy") }} (6:00 AM to 6:00 AM) · CAMPAIGN {{ camp }} · CAMPAIGN DAY {{ C.days }}</div>

{# ===================== PRODUCTION ===================== #}
<div class="band">PRODUCTION</div>
<table>
  <colgroup>
    <col style="width:6.5%"><col style="width:4%"><col style="width:4%"><col style="width:4%">
    <col style="width:4.4%"><col style="width:4.4%"><col style="width:4.4%"><col style="width:4.4%"><col style="width:4.4%"><col style="width:4.4%"><col style="width:4.4%">
    <col style="width:4.6%"><col style="width:4.6%"><col style="width:4.6%"><col style="width:4.6%"><col style="width:4.6%">
    <col style="width:5.5%"><col style="width:5%"><col style="width:5%"><col style="width:5%">
  </colgroup>
  <tr><th rowspan="2" class="lbl">Section</th><th rowspan="2">CMP No.</th><th rowspan="2">CMP Day</th><th rowspan="2">Feed Rate</th>
      <th colspan="7">Production (MT)</th><th colspan="5">Quality at Cooler Discharge</th><th colspan="4">GENERATION</th></tr>
  <tr><th>TDY</th><th>MTD</th><th>Target</th><th>CMP</th><th>YTD</th><th>Target</th><th>Actual %</th>
      <th>Avg Fe(M)</th><th>A Gr. TDY</th><th>% A Gr. TDY</th><th>B Gr. TDY</th><th>% B Gr. TDY</th>
      <th></th><th>TODAY</th><th>MONTH</th><th>YEARLY</th></tr>
  <tr><td class="lbl">{{ kiln|upper }}</td><td class="c">{{ camp }}</td><td class="c">{{ C.days }}</td><td class="c">{{ div(T.feed, 1, 1) if FEED_RATE_FIELD else NA }}</td>
      <td class="r b">{{ n0(T.dri) }}</td><td class="r">{{ n0(M.dri) }}</td><td class="r">{{ n0(target_mtd) }}</td><td class="r">{{ n0(C.dri) }}</td><td class="r">{{ n0(Y.dri) }}</td>
      <td class="r">{{ n0(target_ytd) }}</td><td class="r">{{ div(Y.dri, target_ytd, 1, 100) }}</td>
      <td class="r">{{ div(T.fe_num, T.fe_den) }}</td><td class="r">{{ n1(T.a_hrs) }}</td><td class="r">{{ div(T.a_hrs, T.a_hrs + T.b_hrs, 1, 100) }}</td><td class="r">{{ n1(T.b_hrs) }}</td><td class="r">{{ div(T.b_hrs, T.a_hrs + T.b_hrs, 1, 100) }}</td>
      <td class="lbl c">Power MW</td><td class="r">{{ div(T.kwh, 24000) }}</td><td class="r">{{ div(M.kwh, M.days * 24000) }}</td><td class="r">{{ div(Y.kwh, Y.days * 24000) }}</td></tr>
  <tr><td colspan="11" class="nb"></td>
      <th>Avg Fe(M)</th><th>A Gr. MTD</th><th>% A Gr. MTD</th><th>B Gr. MTD</th><th>% B Gr. MTD</th>
      <td class="lbl c">Steam TPH</td><td class="r">{{ div(T.steam, 24, 1) }}</td><td class="r">{{ div(M.steam, M.days * 24, 1) }}</td><td class="r">{{ div(Y.steam, Y.days * 24, 1) }}</td></tr>
  <tr><td colspan="11" class="nb"></td>
      <td class="r">{{ div(M.fe_num, M.fe_den) }}</td><td class="r">{{ n1(M.a_hrs) }}</td><td class="r">{{ div(M.a_hrs, M.a_hrs + M.b_hrs, 1, 100) }}</td><td class="r">{{ n1(M.b_hrs) }}</td><td class="r">{{ div(M.b_hrs, M.a_hrs + M.b_hrs, 1, 100) }}</td>
      <td colspan="4" class="nb"></td></tr>
</table>

<div class="gap"></div>
<table class="outer"><tr>
  {# Breakdown details + feed loss #}
  <td style="width:30.5%">
    <table>
      <colgroup><col style="width:22%"><col style="width:13%"><col style="width:13%"><col style="width:13%"><col style="width:13%"><col style="width:26%"></colgroup>
      <tr><th colspan="6">BREAKDOWN DETAILS (MINS)</th></tr>
      <tr><th class="lbl">Section</th>{% for g in BD_COLS %}<th>{{ g }}</th>{% endfor %}</tr>
      <tr><td class="lbl">{{ kiln|upper }}</td>{% for g in BD_COLS %}<td class="wrap" style="font-size:8.5px">{{ bd_notes.get(g, "") }}</td>{% endfor %}</tr>
      {% for label, s in [("Day Total", "tdy"), ("Month Total", "mtd"), ("Campaign", "cmp"), ("YEAR TOTAL", "ytd")] %}
      <tr><td class="lbl">{{ label }}</td>{% for g in BD_COLS %}<td class="r">{{ nz(BD[g][s]) }}</td>{% endfor %}</tr>
      {% endfor %}
    </table>
    <div class="gap"></div>
    <table>
      <colgroup><col style="width:22%"><col style="width:26%"><col style="width:52%"></colgroup>
      <tr><th class="lbl">FEED LOSS (MINS)</th><th>Reasons</th><th>Remarks</th></tr>
      {% for r in feed_today[:6] %}<tr><td class="r">{{ nz(r.mins) }}</td><td class="c">{{ r.dept or NA }}</td><td class="wrap">{{ r.remarks or NA }}</td></tr>{% endfor %}
      {% if not feed_today %}<tr><td class="r">{{ NA }}</td><td class="c">{{ NA }}</td><td class="c">{{ NA }}</td></tr>{% endif %}
      {% for i in range(6 - [feed_today|length, 1]|max) %}<tr><td></td><td></td><td></td></tr>{% endfor %}
    </table>
  </td>
  {# Kiln shutdown details (source to be confirmed) #}
  <td style="width:14.5%">
    <table>
      <colgroup><col style="width:34%"><col style="width:33%"><col style="width:33%"></colgroup>
      <tr><th colspan="3">KILNS SHUTDOWN DETAILS</th></tr>
      <tr><th></th><th>S/D Month</th><th>Cast. Cons</th></tr>
      <tr><td class="lbl">DURATION</td><td class="c">{{ NA }}</td><td class="c">{{ NA }}</td></tr>
      {% for i in range(12) %}<tr><td></td><td></td><td></td></tr>{% endfor %}
    </table>
  </td>
  {# ABP production by month #}
  <td style="width:17.5%">
    <table>
      <colgroup><col style="width:22%"><col style="width:26%"><col style="width:26%"><col style="width:26%"></colgroup>
      <tr><th colspan="4">ABP PRODUCTION (MT)</th></tr>
      <tr><th>Month</th><th>TARGET</th><th>Actual</th><th>Deviation</th></tr>
      {% set tot = namespace(t=0, a=0) %}
      {% for i in range(12) %}
        {% set ms = U.add_months(fy_start, i) %}{% set key_m = (ms|string)[:7] %}
        {% set act = mdri.get(key_m) if ms <= day else none %}
        {% set tgt = ABP_MONTHLY[i] %}
        {% set tot.t = tot.t + tgt %}{% if act is not none %}{% set tot.a = tot.a + act %}{% endif %}
        <tr><td class="g">{{ ms.strftime("%b") }}</td><td class="r">{{ n0(tgt) }}</td><td class="r">{{ n0(act) if act is not none else NA }}</td><td class="r">{% if act is none %}{{ NA }}{% elif ms < mstart %}{{ n0(act - tgt) }}{% else %}{{ n0(act - tgt * day.day / dim) }}*{% endif %}</td></tr>
      {% endfor %}
      <tr><td class="g">Total</td><td class="r b">{{ n0(tot.t) }}</td><td class="r b">{{ n0(tot.a) }}</td><td class="r b"></td></tr>
    </table>
    <div class="muted" style="font-size:8px">* current month: against its pro-rata target</div>
  </td>
  {# Ever best production + yearly target #}
  <td style="width:37.5%">
    <table class="outer"><tr>
      <td style="width:50%">
        <table>
          <colgroup><col style="width:30%"><col style="width:35%"><col style="width:35%"></colgroup>
          <tr><th colspan="3">Ever Best Production (MT)</th></tr>
          <tr><th></th><th>Production</th><th>Period</th></tr>
          {% set bq = best_of(BEST.q).split("|") %}{% set bh = best_of(BEST.h).split("|") %}{% set by = best_of(BEST.y).split("|") %}
          <tr><td class="lbl">Day</td><td class="r">{{ n0(best_day[0].dri) if best_day else NA }}</td><td class="c">{{ frappe.format_date(best_day[0].d, "dd MMM yyyy") if best_day else NA }}</td></tr>
          <tr><td class="lbl">Month</td><td class="r">{{ n0(best_month.v) if best_month.k else NA }}</td><td class="c">{{ frappe.format_date(best_month.k ~ "-01", "MMM yyyy") if best_month.k else NA }}</td></tr>
          <tr><td class="lbl">Quarter</td><td class="r">{{ n0(bq[1]) if bq[0] else NA }}</td><td class="c">{{ bq[0] or NA }}</td></tr>
          <tr><td class="lbl">Half year</td><td class="r">{{ n0(bh[1]) if bh[0] else NA }}</td><td class="c">{{ bh[0] or NA }}</td></tr>
          <tr><td class="lbl">Year</td><td class="r">{{ n0(by[1]) if by[0] else NA }}</td><td class="c">{{ by[0] or NA }}</td></tr>
        </table>
      </td>
      <td style="width:50%">
        {% set bal_days = fy_days - fy_elapsed %}
        <table>
          <colgroup><col style="width:74%"><col style="width:26%"></colgroup>
          <tr><th colspan="2">YEARLY TARGET · FY {{ fy_y }}-{{ "%02d"|format((fy_y + 1) % 100) }}</th></tr>
          <tr><td class="lbl">YEARLY TARGET (MT)</td><td class="r b">{{ n0(TARGET_YEAR) }}</td></tr>
          <tr><td class="lbl">PRODUCED TILL DATE (MT)</td><td class="r">{{ n0(Y.dri) }}</td></tr>
          <tr><td class="lbl">BALANCE TO TARGET (MT)</td><td class="r">{{ n0(TARGET_YEAR - Y.dri) }}</td></tr>
          <tr><td class="lbl">BALANCE DAYS</td><td class="r">{{ bal_days }}</td></tr>
          <tr><td class="lbl">AVG. PROD. REQ./DAY (MT)</td><td class="r b">{{ div(TARGET_YEAR - Y.dri, bal_days, 1) }}</td></tr>
          <tr><td class="lbl">AVG. PROD./DAY TILL DATE (MT)</td><td class="r">{{ div(Y.dri, Y.days, 1) }}</td></tr>
        </table>
      </td>
    </tr></table>
  </td>
</tr></table>

{# ===================== MATERIAL ===================== #}
<div class="band">MATERIAL</div>
{% set LAB_IRON = ["Moisture", "Fe(T)", "L.O.I.", "MAG", "SiO2 + Al2O3", "P", "Ti", "Al", "+18mm", "-5mm", "FeO"] %}
{% set LAB_DOLO = ["Mois", "LOI", "CaO", "MgO", "SiO2", "Al2O3", "+8mm", "-2mm"] %}
{% set LAB_COAL = ["Mois", "VM", "Ash", "FC", "GCV", "Sulp", "+30mm", "+20mm", "+5mm", "+3mm", "-3mm"] %}
<table class="outer"><tr>
  {# Raw material consumption and specific consumption #}
  <td style="width:20.5%">
    <table>
      <colgroup><col style="width:34%"><col style="width:22%"><col style="width:22%"><col style="width:22%"></colgroup>
      <tr><th></th><th></th><th>TDY</th><th>MTD</th></tr>
      {% set rmc = [("I/O", "ore"), ("Pellets", "pel"), ("IM COAL", "rb2"), ("DOM COAL", "dom"), ("WASH COAL", "wash"), ("Dolo", "dolo")] %}
      {% for label, f in rmc %}
      <tr>{% if loop.first %}<td rowspan="6" class="lbl wrap c">Raw Materials Cons. (MT)</td>{% endif %}<td class="g">{{ label }}</td><td class="r">{{ nz(T[f], 1) }}</td><td class="r">{{ nz(M[f], 1) }}</td></tr>
      {% endfor %}
      <tr><td rowspan="7" class="lbl wrap c">Specific Consumption (per MT DRI)</td><td class="g">Power</td><td class="r">{{ div(T.dri_kwh, T.dri, 0) }}</td><td class="r">{{ div(M.dri_kwh, M.dri, 0) }}</td></tr>
      {% for label, f in rmc %}
      <tr><td class="g">{{ label }}</td><td class="r">{{ per(T[f], T.dri, 3 if f == "dolo" else 2) }}</td><td class="r">{{ per(M[f], M.dri, 3 if f == "dolo" else 2) }}</td></tr>
      {% endfor %}
    </table>
  </td>
  {# ABP specific consumption: target vs till date (FY) #}
  <td style="width:14.5%">
    <table>
      <colgroup><col style="width:40%"><col style="width:30%"><col style="width:30%"></colgroup>
      <tr><th colspan="3">ABP SPEC CONS</th></tr>
      <tr><th>Material</th><th>Target</th><th>Till Date</th></tr>
      {# blank when nothing of that material was used this year #}
      {% for label, k, v in [("Sp. Pellets", "pellets", per(Y.pel, Y.dri)), ("Sp. Iron", "iron", per(Y.ore, Y.dri)), ("Sp. Coal", "coal", per(Y.coal, Y.dri)), ("Sp. IM Coal", "im_coal", per(Y.rb2, Y.dri)),
                             ("Sp. Power", "power", per(Y.dri_kwh, Y.dri, 0)), ("Sp. Water", "water", NA), ("Sp. Store", "store", n0(STORE.ytd.values()|sum) if STORE.ytd else NA), ("Sp. Dolo", "dolo", per(Y.dolo, Y.dri, 3))] %}
      <tr><td class="g">{{ label }}</td><td class="r">{{ ABP_SPEC[k] if ABP_SPEC[k] is not none else NA }}</td><td class="r">{{ v }}</td></tr>
      {% endfor %}
      <tr><th colspan="3">Coal Ratio (D Coal : I Coal) · till date</th></tr>
      <tr><td class="g">I COAL %</td><td class="r" colspan="2">{{ div(Y.rb2, Y.coal, 1, 100) }}</td></tr>
      <tr><td class="g">D COAL %</td><td class="r" colspan="2">{{ div(Y.dcoal, Y.coal, 1, 100) }}</td></tr>
    </table>
  </td>
  {# Lab analysis (latest values from "Quality Query" when available) #}
  {% for title, rm, rows in [("Iron Ore", "IO", LAB_IRON), ("Pellets", "PELLETS", LAB_IRON), ("Dolomite", "DOLOMITE", LAB_DOLO)] %}
  <td style="width:9%">
    <table>
      <colgroup><col style="width:55%"><col style="width:45%"></colgroup>
      <tr><th colspan="2">{{ title }}</th></tr>
      {% for p in rows %}<tr><td class="g">{{ p }}</td><td class="r">{{ lab(rm, p) }}</td></tr>{% endfor %}
    </table>
  </td>
  {% endfor %}
  <td style="width:20%">
    <table>
      <colgroup><col style="width:24%"><col style="width:19%"><col style="width:19%"><col style="width:19%"><col style="width:19%"></colgroup>
      <tr><th>COAL</th><th>RB-1</th><th>RB-2</th><th>WASH COAL</th><th>DOM</th></tr>
      {% for p in LAB_COAL %}<tr><td class="g">{{ p }}</td><td class="r">{{ lab("RB1", p) }}</td><td class="r">{{ lab("RB2", p) }}</td><td class="r">{{ lab("WASH", p) }}</td><td class="r">{{ lab("DOM", p) }}</td></tr>{% endfor %}
    </table>
  </td>
  {# Store consumption (source to be confirmed) #}
  <td style="width:9%">
    <table>
      <colgroup><col style="width:40%"><col style="width:30%"><col style="width:30%"></colgroup>
      <tr><th colspan="3">Store Consumption (Rs./Ton)</th></tr>
      <tr><th>Section</th><th>Today</th><th>FY</th></tr>
      {% set secs = STORE_SECTIONS|map(attribute=0)|list + (["Other"] if STORE.tdy.get("Other") or STORE.ytd.get("Other") else []) %}
      {% for s in secs %}<tr><td class="g">{{ s }}</td><td class="r">{{ nz(STORE.tdy.get(s)) }}</td><td class="r">{{ nz(STORE.ytd.get(s)) }}</td></tr>{% endfor %}
      <tr><td class="g">Total</td><td class="r b">{{ nz(STORE.tdy.values()|sum) }}</td><td class="r b">{{ nz(STORE.ytd.values()|sum) }}</td></tr>
    </table>
  </td>
</tr></table>

{# ===================== STOCK / LOGISTICS ===================== #}
<div class="band">STOCK / LOGISTICS</div>
<table class="outer"><tr>
  <td style="width:35%">
    <table>
      <colgroup><col style="width:22%"><col style="width:13%"><col style="width:13%"><col style="width:13%"><col style="width:39%"></colgroup>
      <tr><th colspan="5" class="lbl">DRI #{{ (kiln|upper)|replace("KILN", "")|replace("-", "")|replace("#", "")|replace("NO", "")|replace(".", "")|trim }} Sponge Iron Dispatch Report</th></tr>
      <tr><th></th><th>TDY</th><th>MTD</th><th>YTD</th><th>Remark</th></tr>
      {# outward weighbridge net MT; "--" for products without an item code yet #}
      {% set dt = namespace(tdy=0, mtd=0, ytd=0) %}
      {% for label, codes in DISPATCH %}
        {% set v = {"tdy": wb(codes, "outward", "tdy"), "mtd": wb(codes, "outward", "mtd"), "ytd": wb(codes, "outward", "ytd")} %}
        {% if codes %}{% set dt.tdy = dt.tdy + (v.tdy|float) %}{% set dt.mtd = dt.mtd + (v.mtd|float) %}{% set dt.ytd = dt.ytd + (v.ytd|float) %}{% endif %}
        <tr><td class="g">{{ label }}</td>{% for sc in ["tdy", "mtd", "ytd"] %}<td class="r">{{ nz(v[sc], 1) if codes else NA }}</td>{% endfor %}<td class="c muted" style="font-size:8.5px">{{ codes|join(" + ") if codes else "item code to confirm" }}</td></tr>
      {% endfor %}
      <tr><td class="g">Total</td><td class="r b">{{ nz(dt.tdy, 1) }}</td><td class="r b">{{ nz(dt.mtd, 1) }}</td><td class="r b">{{ nz(dt.ytd, 1) }}</td><td></td></tr>
    </table>
  </td>
  <td style="width:26.5%">
    <table>
      <colgroup><col style="width:20%"><col style="width:16%"><col style="width:16%"><col style="width:16%"><col style="width:16%"><col style="width:16%"></colgroup>
      <tr><th colspan="6">Product Stock Report</th></tr>
      <tr><th></th><th>LUMPS</th><th>FINES</th><th>CHAR</th><th>Total</th><th>ERP</th></tr>
      {# OPENING / CLOSING: book stock (MT) from the stock ledger at 6 AM on the day and the next day #}
      <tr><td class="g">P/H</td>{% for i in range(5) %}<td class="c">{{ NA }}</td>{% endfor %}</tr>
      {% for label, key in [("OPENING", "open"), ("CLOSING", "close")] %}
        {% set tt = namespace(v=0, any=false) %}
        <tr><td class="g">{{ label }}</td>
          {% for _n, codes in PRODUCT_STOCK %}{% set v = stk(codes, key) %}{% if v != "" %}{% set tt.v = tt.v + (v|float) %}{% set tt.any = true %}{% endif %}<td class="r">{{ n1(v) if v != "" else NA }}</td>{% endfor %}
          <td class="r b">{{ n1(tt.v) if tt.any else NA }}</td><td class="r">{{ n1(tt.v) if tt.any else NA }}</td></tr>
      {% endfor %}
      <tr><td class="g">TOTAL</td>{% for i in range(5) %}<td class="c">{{ NA }}</td>{% endfor %}</tr>
    </table>
  </td>
  <td style="width:38.5%">
    <table>
      <colgroup><col style="width:22%"><col style="width:13%"><col style="width:13%"><col style="width:13%"><col style="width:13%"><col style="width:13%"><col style="width:13%"></colgroup>
      <tr><th colspan="7">Raw Material Balancing (Yard to Yard) on 06:00 to 06:00</th></tr>
      <tr><th>Material</th><th>Op. Stock</th><th>Day's Recd.</th><th>Day's Cons.</th><th>Physical</th><th>Closing Stock</th><th>DIFF.</th></tr>
      {# Op. stock: stock ledger at 6 AM · Recd.: weighbridge inward 6 AM – 6 AM · Cons.: DRI Production (all kilns) · Closing = Op. + Recd. − Cons. #}
      {% for label, codes, f in RM_BALANCE %}
        {% set op = stk(codes, "open") if codes else "" %}
        {% set rc = wb(codes, "inward", "tdy") if codes else "" %}
        {% set cs = PC[f] if f else none %}
        <tr><td class="g" style="text-align:left">{{ label }}</td>
          <td class="r">{{ n1(op) if op != "" else NA }}</td>
          <td class="r">{{ nz(rc, 1) if rc != "" else NA }}</td>
          <td class="r">{{ nz(cs, 1) if cs is not none else NA }}</td>
          <td class="c">{{ NA }}</td>
          <td class="r">{{ n1((op|float) + (rc|float if rc != "" else 0) - (cs or 0)|float) if op != "" else NA }}</td>
          <td class="c">{{ NA }}</td></tr>
      {% endfor %}
    </table>
  </td>
</tr></table>
</div>
